from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> {'borrowed_by': user, 'borrowed_on': date} or None if available
        self.users = {}  # user -> {'current_book': book_id, 'fines': float, 'borrow_history': [(book_id, borrow_date, return_date, fine)]}

    def add_book(self, book_id: str) -> None:
        self.books[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user has unpaid fines and already holds a book
        if user in self.users and self.users[user]['fines'] > 0:
            if self.users[user].get('current_book') is not None:
                raise ValueError(f"User {user} has unpaid fines and already holds a book")

        # Record the borrowing
        self.books[book_id] = {'borrowed_by': user, 'borrowed_on': day}

        # Initialize user if not exists
        if user not in self.users:
            self.users[user] = {'current_book': book_id, 'fines': 0.0, 'borrow_history': []}
        else:
            self.users[user]['current_book'] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        book_info = self.books[book_id]
        if book_info is None:
            raise ValueError(f"Book {book_id} is not currently borrowed")

        if book_info['borrowed_by'] != user:
            raise ValueError(f"User {user} did not borrow book {book_id}")

        # Calculate fine
        borrow_date = book_info['borrowed_on']
        fine = 0.0

        # Calculate number of business days overdue (excluding weekends)
        if day > borrow_date:
            # Calculate days between borrow_date + loan_days and day (inclusive of day, exclusive of due date)
            due_date = borrow_date + timedelta(days=self.loan_days)
            if day > due_date:
                # Count business days from due_date + 1 to day (inclusive)
                current = due_date + timedelta(days=1)
                while current <= day:
                    # Skip weekends (Saturday=5, Sunday=6)
                    if current.weekday() < 5:  # Monday=0, Friday=4
                        fine += self.daily_fine
                    current += timedelta(days=1)

        # Update user's fines
        if user in self.users:
            self.users[user]['fines'] += fine
            # Remove current book reference
            self.users[user]['current_book'] = None
            # Add to history
            self.users[user]['borrow_history'].append((book_id, borrow_date, day, fine))

        # Mark book as available
        self.books[book_id] = None

        return fine

    def unpaid_fines(self, user: str) -> float:
        if user not in self.users:
            return 0.0
        return self.users[user]['fines']

    def pay(self, user: str) -> None:
        if user in self.users:
            self.users[user]['fines'] = 0.0
